-- Nestly sample data: the demo hostels, owners, students, bookings and reports, loaded into your real database.
-- Run it once in Supabase > SQL Editor, after the four migration files.
--
-- Every sample account's password is nestly123. Sample logins:
--   owner      grace.n                (3 live hostels, a draft sent back, money, staff)
--   owner      daniel.o               (waiting for approval)
--   custodian  peter.k                (Hillview Hostel)
--   student    sarah.atim@ucu.ac.ug   (lives at Hillview)
-- There is no sample admin. Make your own account the admin (see SETUP.md, step 6).
--
-- These accounts have a known password, so remove them before real students use the site:
-- run supabase/remove_sample_data.sql.

set search_path = public, extensions;
begin;

-- Accounts. The sign-up rules make every new account a student or an owner, so each one is then set to its real role.


-- Universities' teaching calendars.
update public.universities set sems = '[{"start":"2027-01-11","end":"2027-05-14"},{"start":"2027-08-09","end":"2027-12-10"}]'::jsonb where id = 'ucu';
update public.universities set sems = '[{"start":"2027-01-18","end":"2027-05-21"},{"start":"2027-08-16","end":"2027-12-17"}]'::jsonb where id = 'mak';

